#!/bin/sh
set -eu

export ENABLE_EXPERIMENTAL_COMPILER=true
export SCALANATIVE_TEST_PREFETCH_DEBUG_INFO=1
export SCALANATIVE_TEST_DEBUG_SIGNALS=1

# The checkout retains the host runner's UID when copied into the root-run VM.
git config --global --add safe.directory "$PWD"
# The VM hostname is not necessarily published in DNS or its base hosts file.
printf '127.0.0.1 %s\n' "$(hostname)" >> /etc/hosts

uname -a
java -version
clang --version
# --server avoids the native thin client, which is not available for BSD.
# DEBUG(bsd-spurious-so): run suspected tests concurrently, many times.
sbt --server --batch --sbt-version "$SBT_VERSION" \
  "tests3/testOnly org.scalanative.testsuite.javalib.nio.file.FilesCreateDirectoryTest org.scalanative.testsuite.javalib.lang.ObjectMonitorTest scala.scalanative.runtime.GarbageCollectorTest scala.scalanative.runtime.ContinuationsTest org.scalanative.testsuite.javalib.io.PipedInputStreamTest org.scalanative.testsuite.javalib.util.concurrent.ScheduledExecutorTest org.scalanative.testsuite.javalib.lang.StackOverflowTest" "tests3/testOnly org.scalanative.testsuite.javalib.nio.file.FilesCreateDirectoryTest org.scalanative.testsuite.javalib.lang.ObjectMonitorTest scala.scalanative.runtime.GarbageCollectorTest scala.scalanative.runtime.ContinuationsTest org.scalanative.testsuite.javalib.io.PipedInputStreamTest org.scalanative.testsuite.javalib.util.concurrent.ScheduledExecutorTest org.scalanative.testsuite.javalib.lang.StackOverflowTest" "tests3/testOnly org.scalanative.testsuite.javalib.nio.file.FilesCreateDirectoryTest org.scalanative.testsuite.javalib.lang.ObjectMonitorTest scala.scalanative.runtime.GarbageCollectorTest scala.scalanative.runtime.ContinuationsTest org.scalanative.testsuite.javalib.io.PipedInputStreamTest org.scalanative.testsuite.javalib.util.concurrent.ScheduledExecutorTest org.scalanative.testsuite.javalib.lang.StackOverflowTest" "tests3/testOnly org.scalanative.testsuite.javalib.nio.file.FilesCreateDirectoryTest org.scalanative.testsuite.javalib.lang.ObjectMonitorTest scala.scalanative.runtime.GarbageCollectorTest scala.scalanative.runtime.ContinuationsTest org.scalanative.testsuite.javalib.io.PipedInputStreamTest org.scalanative.testsuite.javalib.util.concurrent.ScheduledExecutorTest org.scalanative.testsuite.javalib.lang.StackOverflowTest" "tests3/testOnly org.scalanative.testsuite.javalib.nio.file.FilesCreateDirectoryTest org.scalanative.testsuite.javalib.lang.ObjectMonitorTest scala.scalanative.runtime.GarbageCollectorTest scala.scalanative.runtime.ContinuationsTest org.scalanative.testsuite.javalib.io.PipedInputStreamTest org.scalanative.testsui